def transform(grid):
    h=len(grid); w=len(grid[0]); frame=grid[0][0]
    leftw=next((j for j,x in enumerate(grid[0]) if x==0),w)
    divs=[i for i,row in enumerate(grid) if all(x==frame for x in row[:leftw])]
    out=[row[:leftw] for row in grid]
    rightcols=list(range(leftw+1,w-1))
    objects={}
    for a,b in zip(divs,divs[1:]):
        colors={grid[i][j] for i in range(a+1,b) for j in rightcols if grid[i][j]!=0}
        for color in colors:
            mask=tuple(tuple(int(grid[i][j]==color) for j in rightcols) for i in range(a+1,b))
            objects[mask]=color
    for a,b in zip(divs,divs[1:]):
        hole=tuple(tuple(int(grid[i][j]==0) for j in range(1,leftw-1)) for i in range(a+1,b))
        if hole not in objects: raise ValueError((hole,objects))
        color=objects[hole]
        for i in range(a+1,b):
            for j in range(1,leftw-1):
                if out[i][j]==0: out[i][j]=color
